"""Concorrência de conjuntos somente em banco isolado; não executar em produção."""
import concurrent.futures,json,os,secrets,subprocess,uuid
if os.environ.get('MUKIRANA_TEST_DATABASE_ISOLATED')!='1':raise SystemExit('Exige banco isolado e MUKIRANA_TEST_DATABASE_ISOLATED=1.')
PSQL=json.loads(os.environ.get('MUKIRANA_TEST_PSQL','["psql","-v","ON_ERROR_STOP=1","-Atq"]'))
def sql(source):
 r=subprocess.run(PSQL,input=source,text=True,capture_output=True,check=True);return [json.loads(line) for line in r.stdout.splitlines() if line.startswith('{')]
def pair(first,second):
 with concurrent.futures.ThreadPoolExecutor(max_workers=2) as p:return [f.result() for f in [p.submit(sql,first),p.submit(sql,second)]]
u,a,c,g,old=[str(uuid.uuid4()) for _ in range(5)];token=secrets.token_hex(32)
def create(id,renew=None,version=None):return f"select public.mukirana_occurrences_create('{token}','{id}','expense','Conjunto',900,'2027-01-31','monthly','{'recurring' if renew else 'installment'}',{('null' if renew else 3)},{(3 if renew else 'null')},'{a}','{c}','variable',{'null' if not renew else chr(39)+renew+chr(39)},{version if version is not None else 'null'});"
def state(id):return sql(f"select json_build_object('version',g.version,'rows',(select count(*) from mukirana_private.transactions where group_id=g.id),'first',(select json_build_object('id',t.id,'version',t.version) from mukirana_private.transactions t where group_id=g.id order by occurrence_index limit 1)) from mukirana_private.transaction_groups g where id='{id}';")[0]
def change(s,action='save',amount=300):return f"select public.mukirana_occurrences_change('{token}','{g}',{s['version']},'{s['first']['id']}',{s['first']['version']},'{uuid.uuid4()}','{action}','all','{json.dumps({'amountCents':amount}) if action=='save' else '{}'}'::jsonb);"
sql(f"insert into mukirana_private.users(id,email) values('{u}','occurrences-concurrency-{u}@example.invalid');insert into mukirana_private.sessions(token_hash,user_id,expires_at) values(encode(extensions.digest('{token}','sha256'),'hex'),'{u}',clock_timestamp()+interval '1 hour');select public.mukirana_accounts_save('{token}','{a}',0,'Banco','consumption',null,false);select public.mukirana_categories_save('{token}','{c}',0,'Pessoal',null);")
checks=[]
try:
 r=pair('begin;'+create(g)+'select pg_sleep(0.3);commit;',create(g));assert all(x[0]['status']=='saved' for x in r);s=state(g);assert s['rows']==3;checks.append('criações concorrentes idempotentes geram um único conjunto')
 r=pair(change(s,amount=400),change(s,amount=500));assert sorted(x[0]['status'] for x in r)==['conflict','saved'];amounts=sql(f"select json_build_object('values',count(distinct amount_cents),'rows',count(*)) from mukirana_private.transactions where group_id='{g}';")[0];assert amounts=={'values':1,'rows':3};checks.append('dois lotes concorrentes preservam um único resultado integral')
 s=state(g);legacy=f"select public.mukirana_transactions_save('{token}','{s['first']['id']}',{s['first']['version']},'expense','Edição individual',700,'2027-01-31','{a}','{c}','variable');";r=pair(legacy,change(s,amount=600));assert sorted(x[0]['status'] for x in r)==['conflict','saved'];checks.append('edição individual legada invalida lote com versão antiga')
 s=state(g);r=pair(change(s,'delete'),change(s,amount=800));assert sorted(x[0]['status'] for x in r) in [['conflict','deleted'],['conflict','saved']];assert state(g)['rows'] in [0,3];checks.append('exclusão e edição concorrentes não deixam lote parcial')
 sql(f"insert into mukirana_private.transaction_groups(id,user_id,nature,modality,frequency,start_on,anchor_day,duration_months,planned_count,creation_hash,created_at) values('{old}','{u}','expense','recurring','monthly','2026-01-31',31,1,1,'fixture','2026-01-01');insert into mukirana_private.transactions(user_id,nature,description,amount_cents,occurred_on,account_id,category_id,classification,modality,group_id,occurrence_index) values('{u}','expense','Antiga',100,'2026-01-31','{a}','{c}','fixed','recurring','{old}',1);")
 v=state(old)['version'];r=pair(create(str(uuid.uuid4()),old,v),create(str(uuid.uuid4()),old,v));assert sorted(x[0]['status'] for x in r)==['already_renewed','saved'];n=sql(f"select json_build_object('count',count(*)) from mukirana_private.transaction_groups where renewed_from_id='{old}';")[0];assert n['count']==1;checks.append('duas renovações simultâneas não duplicam ocorrências')
 print(json.dumps({'passed':len(checks),'checks':checks},ensure_ascii=False,indent=2))
finally:
 sql(f"delete from mukirana_private.transactions where user_id='{u}';delete from mukirana_private.transaction_groups where user_id='{u}' and renewed_from_id is not null;delete from mukirana_private.transaction_groups where user_id='{u}';delete from mukirana_private.categories where user_id='{u}';delete from mukirana_private.accounts where user_id='{u}';delete from mukirana_private.sessions where user_id='{u}';delete from mukirana_private.users where id='{u}';")
